{
    // Unpack the 32-bit integer into two 16-bit half-precision values
    float2 result;
    result.x = f16tof32((packedValue >> 16) & 0xFFFF);
    result.y = f16tof32(packedValue & 0xFFFF);
    return result;
}

uint packFloat2ToUint(float2 value)
{
    // Convert each float to a 16-bit half-precision value
    uint half1 = f32tof16(value.x);
    uint half2 = f32tof16(value.y);

    // Combine the two 16-bit half-precision values into a 32-bit integer
    uint packedValue = (half1 << 16) | half2;

    return packedValue;
}
```

### Unpacking `uint` to `float2`

